// Valida o shared secret (opcional). Defina a variável
// SYNAPSEOS_WEBHOOK_SECRET em 'Settings → Variables' para ativar.
const expected = $env.SYNAPSEOS_WEBHOOK_SECRET;
const headers = $input.first().json.headers || {};
const received = headers['x-synapseos-signature'] || headers['X-Synapseos-Signature'] || '';
if (expected && expected !== received) {
  throw new Error('Invalid X-Synapseos-Signature');
}

// Normaliza o payload do Chatwoot para o contrato da Hyperflow:
// { to, type, payload }
// O Chatwoot usa 'document' para arquivos; a Hyperflow usa 'file'.
const body = $input.first().json.body || {};
const typeMap = { document: 'file' };
const outgoingType = typeMap[body.type] || body.type;

return [{
  json: {
    hyperflow_request: {
      to: body.to,
      type: outgoingType,
      payload: body.payload
    },
    chatwoot_message_id: body.chatwoot_message_id,
    chatwoot_conversation_id: body.chatwoot_conversation_id,
    chatwoot_inbox_id: body.chatwoot_inbox_id
  }
}];
